// Campaign-level approval model (2026-07-02): approving the brief authorizes the
// cadence. Steps whose action_type is in app_config.approval_required_channels
// (default phone,partner) still need a per-step click; everything else is
// auto-approved right after this digest is sent (see Build Auto Approvals ->
// Auto Approve Executed Steps, which replay /webhook/action-approval with
// src=auto so the handler skips its per-action email).
// 2026-07-02 (E): pre-approved cards also carry one-click "log outcome" links
// (GET /webhook/engagement) so a reply/call lands in engagement_events without
// the rep ever opening a dashboard.
const dueSteps = $('Find Due Steps').all().map(i => i.json);
const newActions = $('Insert Due Action').all().map(i => i.json);
const crypto = require('crypto');
const cfg = $('Get HMAC Secret').first().json;
const SECRET = cfg.value;
const gatedChannels = String(cfg.approval_required_channels || 'phone,partner').split(',').map(s => s.trim()).filter(Boolean);
function hmac(msg) { return crypto.createHmac('sha256', SECRET).update(msg).digest('hex').slice(0, 32); }
const base = 'https://designprodigy.app.n8n.cloud/webhook/action-approval';
const digestBase = 'https://designprodigy.app.n8n.cloud/webhook/digest-approval';
const engBase = 'https://designprodigy.app.n8n.cloud/webhook/engagement';
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const CHANNEL = { email: 'Email', phone: 'Phone call', call_phone: 'Phone call', linkedin_dm: 'LinkedIn DM', linkedin_connect: 'LinkedIn connect', ads: 'Ads', webinar: 'Webinar', partner: 'Partner outreach', content: 'Content share', landing_page: 'Landing page', content_download: 'Content download' };
const OUTCOMES = {
  email: [['reply_or_meeting', 'Got a reply / meeting']],
  phone: [['call_connected', 'Call connected'], ['reply_or_meeting', 'Meeting set']],
  linkedin_dm: [['reply_or_meeting', 'Got a reply']],
  linkedin_connect: [['linkedin_accept', 'Connection accepted']],
  webinar: [['registration', 'They registered']],
  content: [['content_download', 'They downloaded']],
  partner: [['partner_response', 'Partner responded']]
};
const outcomesFor = t => OUTCOMES[t] || [['reply_or_meeting', 'Positive response']];
function outcomeLinks(step, id) {
  return outcomesFor(step.action_type).map(([evt, label]) =>
    `<a href=\"${engBase}?account=${encodeURIComponent(step.account)}&event_type=${evt}&utm_campaign=${encodeURIComponent(step.utm_campaign || '')}&action_id=${id}&source=manual\" style=\"color:#2563eb;text-decoration:none;border:1px solid #dbe3f5;border-radius:8px;padding:4px 10px;font-size:12px;display:inline-block;\">${esc(label)}</a>`
  ).join(' &nbsp;');
}

const items = dueSteps.map((step, idx) => ({ step, action: newActions[idx] || {} })).filter(x => x.action.id);
if (!items.length) return [];

const gated = items.filter(x => gatedChannels.includes(x.step.action_type));
const auto = items.filter(x => !gatedChannels.includes(x.step.action_type));
const n = items.length;

const gatedIds = gated.map(x => x.action.id).join(',');
const approveAllUrl = gated.length ? `${digestBase}?ids=${gatedIds}&sig=${hmac(`digest:${gatedIds}:approve`)}` : '';
const autoUrls = auto.map(x => `${base}?id=${x.action.id}&action=approve&sig=${hmac(`action:${x.action.id}:approve`)}&src=auto`);

function card({ step, action }, i, isGated) {
  const id = action.id;
  const channel = CHANNEL[step.action_type] || step.action_type || 'touch';
  const adaptive = step.adaptive_action ? `<p style=\"margin:6px 0 0;font-size:12px;\"><span style=\"background:#fef3f2;color:#b42318;border-radius:20px;padding:2px 10px;\">&#9888; ${esc(step.adaptive_action)}${step.adaptive_reason ? ' — ' + esc(step.adaptive_reason) : ''}</span></p>` : '';
  const draft = step.outreach_draft ? `<p style=\"margin:8px 0 4px;font-size:12px;color:#5b6472;\"><strong>Ready-to-paste draft:</strong></p><pre style=\"white-space:pre-wrap;background:#f7f8fa;border:1px solid #e4e7ec;border-radius:8px;padding:10px 12px;font-size:13px;font-family:inherit;margin:0;\">${esc(step.outreach_draft)}</pre>` : '<p style=\"font-size:12px;color:#8a93a3;margin:8px 0 0;\">(no draft provided — write your own)</p>';
  const tracked = step.tracked_url ? `<p style=\"margin:8px 0 0;font-size:13px;\">Tracked link to include: <a href=\"${esc(step.tracked_url)}\">${esc(step.tracked_url)}</a></p>` : '';
  let footer;
  if (isGated) {
    const approveUrl = `${base}?id=${id}&action=approve&sig=${hmac(`action:${id}:approve`)}`;
    const skipUrl = `${base}?id=${id}&action=reject&sig=${hmac(`action:${id}:reject`)}&reason=skipped_from_digest`;
    footer = `<p style=\"margin:12px 0 0;\"><a href=\"${approveUrl}\" style=\"background:#16a34a;color:#ffffff;text-decoration:none;border-radius:8px;padding:8px 14px;font-size:13px;display:inline-block;\">&#10003; Approve</a>&nbsp;<a href=\"${skipUrl}\" style=\"color:#b42318;text-decoration:none;border:1px solid #fecdca;border-radius:8px;padding:8px 14px;font-size:13px;display:inline-block;\">Skip</a></p>`;
  } else {
    footer = `<p style=\"margin:12px 0 0;font-size:12px;\"><span style=\"background:#ecfdf3;color:#16a34a;border-radius:20px;padding:3px 10px;\">&#10003; Pre-approved — ready to send</span></p>\n<p style=\"margin:10px 0 0;font-size:12px;color:#5b6472;\">Once you've done it, log the outcome in one click:<br>${outcomeLinks(step, id)}</p>`;
  }
  return `<div style=\"border:1px solid #e4e7ec;border-radius:10px;padding:14px 16px;margin:0 0 12px;\">\n  <p style=\"margin:0;font-size:15px;\"><strong>${i}. ${esc(step.account)}</strong> &nbsp;<span style=\"background:#eef2ff;color:#2563eb;border-radius:20px;font-size:11px;padding:2px 10px;\">${esc(channel)}</span> <span style=\"color:#8a93a3;font-size:11px;\">step ${esc(step.step_number)}</span></p>\n  ${adaptive}\n  <p style=\"margin:6px 0 0;font-size:13px;color:#1f2430;\">To: <strong>${esc(step.target || 'target contact')}</strong></p>\n  ${step.reason ? `<p style=\"margin:6px 0 0;font-size:13px;color:#5b6472;\">Why now: ${esc(step.reason)}</p>` : ''}\n  ${draft}\n  ${tracked}\n  ${footer}\n</div>`;
}

let idx = 0;
const autoSection = auto.length ? `<h3 style=\"font-size:15px;margin:18px 0 10px;\">To do today — pre-approved (${auto.length})</h3>\n${auto.map(x => card(x, ++idx, false)).join('\n')}` : '';
const gatedSection = gated.length ? `<h3 style=\"font-size:15px;margin:18px 0 10px;\">Needs your approval (${gated.length})</h3>\n<p style=\"margin:0 0 12px;\"><a href=\"${approveAllUrl}\" style=\"background:#2563eb;color:#ffffff;text-decoration:none;border-radius:8px;padding:10px 18px;font-size:14px;display:inline-block;\">&#10003; Approve all ${gated.length}</a></p>\n${gated.map(x => card(x, ++idx, true)).join('\n')}` : '';

const subject = `Your ${n} touch${n === 1 ? '' : 'es'} for today${gated.length ? ` (${gated.length} need${gated.length === 1 ? 's' : ''} approval)` : ''}`;
const html = `<div style=\"font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:640px;color:#1f2430;\">\n  <h2 style=\"font-size:18px;margin:0 0 4px;\">${subject}</h2>\n  <p style=\"color:#5b6472;font-size:13px;margin:0 0 8px;\">Approving the brief authorized this cadence — standard touches below are pre-approved with their drafts and tracked links ready. Only high-touch channels (${esc(gatedChannels.join(', ') || 'none')}) still ask for a click. Skips are fed back so the engine learns.</p>\n  ${autoSection}\n  ${gatedSection}\n  <p style=\"color:#8a93a3;font-size:11px;margin-top:16px;\">Sent by Cadence Scheduler &middot; links are single-use per action (already-processed clicks are ignored) &middot; manage from the Pipeline Control Tower dashboard.</p>\n</div>`;

return [{ json: { subject, html, count: n, autoCount: auto.length, gatedCount: gated.length, autoUrls, sendTo: (cfg.rep_email || '').trim() || 'honlamchia@gmail.com' } }];
